import { draftMode } from 'next/headers'
import { NextResponse } from 'next/server'
import { readSignedValue } from '@/lib/security/signed-cookie'

/**
 * Enables Next.js Draft Mode for previewing unpublished content. Accepts the short-lived token
 * generated by the admin ("Vista previa") or `?secret=DRAFT_MODE_SECRET&path=/...` for manual use.
 */
export async function GET(request: Request) {
  const url = new URL(request.url)
  const token = readSignedValue<{ purpose: string; path: string }>(url.searchParams.get('token'))
  const secret = process.env.DRAFT_MODE_SECRET
  const manual = secret && url.searchParams.get('secret') === secret ? url.searchParams.get('path') : null

  const path = token?.purpose === 'draft' ? token.path : manual
  if (!path || !path.startsWith('/') || path.startsWith('//')) {
    return new NextResponse('Invalid preview token', { status: 401 })
  }

  ;(await draftMode()).enable()
  return NextResponse.redirect(new URL(path, url.origin))
}
